        /// 加入会议
        ///
        /// 通过会议号将智能体加入指定的视频会议。调用成功后会返回会议 ID，该 ID 可用于后续的智能体离会、发送会中消息等操作。
        ///
        /// 目前智能体入离会能力灰度中
        ///
        /// - SeeAlso: <https://open.feishu.cn/api-explorer?from=op_doc_tab&apiName=join&project=vc&resource=bot&version=v1>
        ///
        /// `POST /open-apis/vc/v1/bots/join`
        public func join(body: LarkVC.VC.BotJoinBody, options: RequestOptions = .none) async throws -> LarkResponse<LarkVC.VC.BotJoinResponse> {
            try await client.request(.post, "/open-apis/vc/v1/bots/join", query: nil, body: .json(body), options: options)
        }

        /// 获取会议事件列表
        ///
        /// 获取会议中的事件列表，包括参会人加入或离开、发言、聊天、共享等事件
        ///
        /// - SeeAlso: <https://open.feishu.cn/api-explorer?from=op_doc_tab&apiName=events&project=vc&resource=bot&version=v1>
        ///
        /// `GET /open-apis/vc/v1/bots/events`
        public func events(params: LarkVC.VC.BotEventsQuery, options: RequestOptions = .none) async throws -> LarkResponse<LarkVC.VC.BotEventsResponse> {
            try await client.request(.get, "/open-apis/vc/v1/bots/events", query: params, body: .none, options: options)
        }

        /// Iterates over every page of `events` (equivalent of `eventsWithIterator`).
        public func eventsWithIterator(params: LarkVC.VC.BotEventsQuery, options: RequestOptions = .none) -> LarkPageSequence<LarkVC.VC.BotEventsResponse> {
            LarkPageSequence { token in
                var p = params
                if let token { p.pageToken = token }
                let r = try await self.events(params: p, options: options)
                return LarkPage(data: r.data, hasMore: r.data?.hasMore ?? false, nextPageToken: r.data?.pageToken)
            }
        }

    }
}
